// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 rollDelta) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        rollDelta = bound(rollDelta, 0, 1_000_000);

        // Lock at block N with target N+1; after rolling far past 256 blocks,
        // blockhash(N+1) deterministically returns bytes32(0), so settle's answer
        // is known: keccak256(abi.encodePacked(bytes32(0))).
        bytes32 answer = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(answer);

        vm.roll(block.number + 1 + 257 + rollDelta);

        vm.prank(actor);
        c.settle();

        // Rule: with the correct guess locked in, settle always pays the full
        // 2-ether escrow, draining the contract. The mutant keeps guess at 0,
        // never matches, and the balance remains 2 ether.
        assertTrue(address(c).balance == 0);
    }
}
